     9	
    10	import com.loja.orders.common.ApiException;
    11	import com.loja.orders.common.ErrorCode;
    12	import com.loja.orders.common.JsonBodies;
    13	import com.loja.orders.order.OrderItem;
    14	
    15	import tools.jackson.databind.JsonNode;
    16	
    17	/** Lê os dados da compra e faz a primeira conferência: carrinho e cliente ({@code INVALID_ORDER}). */
    18	@Component
    19	public class CheckoutRequestParser {
    20	
    21	    private final JsonBodies bodies;
    22	
    23	    public CheckoutRequestParser(JsonBodies bodies) {
    24	        this.bodies = bodies;
    25	    }
    26	
    27	    public CheckoutRequest parse(String body) {
    28	        JsonNode root = bodies.read(body);
    29	        if (!root.isObject()) {
    30	            throw invalidOrder();
    31	        }
    32	        List<OrderItem> items = items(root.path("items"));
    33	        JsonNode customer = root.path("customer");
    34	        String cpf = JsonBodies.text(customer, "cpf");
    35	        String email = JsonBodies.text(customer, "email");
    36	        if (cpf == null || email == null) {
    37	            throw invalidOrder();
    38	        }
    39	        JsonNode coupon = root.path("coupon");
    40	        boolean couponInformed = !coupon.isMissingNode() && !coupon.isNull();
    41	        return new CheckoutRequest(
    42	                cpf,
    43	                email,
    44	                items,
    45	                JsonBodies.text(root, "zipCode"),
    46	                JsonBodies.text(root, "region"),
    47	                JsonBodies.text(root, "shippingMethod"),
    48	                couponInformed,
    49	                coupon.isString() ? coupon.stringValue() : null,
    50	                JsonBodies.text(root, "paymentMethod"),
    51	                installments(root.path("installments")),
    52	                JsonBodies.text(root, "clubTier"));
    53	    }
    54	
    55	    private static List<OrderItem> items(JsonNode node) {
    56	        if (!node.isArray() || node.isEmpty()) {
    57	            throw invalidOrder();
    58	        }
    59	        List<OrderItem> items = new ArrayList<>();
    60	        Set<String> skus = new HashSet<>();
    61	        for (JsonNode item : node) {
    62	            String sku = JsonBodies.text(item, "sku");
    63	            Integer quantity = integer(item.path("quantity"));
    64	            if (sku == null || !skus.add(sku) || quantity == null || quantity <= 0) {
    65	                throw invalidOrder();
    66	            }
    67	            items.add(new OrderItem(sku, quantity));
    68	        }
    69	        return List.copyOf(items);
    70	    }
    71	
    72	    private static Integer installments(JsonNode node) {
    73	        if (node.isMissingNode() || node.isNull()) {
    74	            return 1;
    75	        }
    76	        return integer(node);
    77	    }
    78	
    79	    private static Integer integer(JsonNode node) {
    80	        if (!node.isNumber() || !node.canConvertToExactIntegral() || !node.canConvertToInt()) {
    81	            return null;
    82	        }
    83	        return node.asInt();
    84	    }
    85	
    86	    private static ApiException invalidOrder() {
    87	        return ApiException.unprocessable(ErrorCode.INVALID_ORDER);
    88	    }
    89	}
