     1	package com.loja.orders.checkout;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.Arrays;
     5	import java.util.Optional;
     6	
     7	import com.loja.orders.common.Money;
     8	
     9	/** Níveis do clube da loja e as vantagens de cada um. Um nível novo é uma linha nova aqui. */
    10	public enum ClubTier {
    11	    BRONZE("0", false, null),
    12	    SILVER("0.02", false, null),
    13	    GOLD("0.05", true, "500.00");
    14	
    15	    private final BigDecimal creditRate;
    16	    private final boolean freeShipping;
    17	    private final BigDecimal giftAbove;
    18	
    19	    ClubTier(String creditRate, boolean freeShipping, String giftAbove) {
    20	        this.creditRate = new BigDecimal(creditRate);
    21	        this.freeShipping = freeShipping;
    22	        this.giftAbove = giftAbove == null ? null : Money.of(giftAbove);
    23	    }
    24	
    25	    public static Optional<ClubTier> fromCode(String code) {
    26	        return Arrays.stream(values()).filter(t -> t.name().equals(code)).findFirst();
    27	    }
    28	
    29	    /** Crédito para a próxima compra, sobre o valor dos produtos. */
    30	    public BigDecimal nextPurchaseCredit(BigDecimal productsSubtotal) {
    31	        return Money.percentOf(productsSubtotal, creditRate);
    32	    }
    33	
    34	    /** Se o nível não paga o frete (nas entregas que o clube cobre). */
    35	    public boolean freeShipping() {
    36	        return freeShipping;
    37	    }
    38	
    39	    public boolean gift(BigDecimal productsSubtotal) {
    40	        return giftAbove != null && productsSubtotal.compareTo(giftAbove) > 0;
    41	    }
    42	}
