    11	 * leva para despachar pelas transportadoras.
    12	 */
    13	public enum Region {
    14	    SOUTHEAST("0.01", null, 0),
    15	    SOUTH("0.01", null, 0),
    16	    MIDWEST("0.015", null, 0),
    17	    NORTH("0.025", "30.00", 3),
    18	    NORTHEAST("0.02", "30.00", 2);
    19	
    20	    private final BigDecimal insuranceRate;
    21	    private final BigDecimal insuranceCap;
    22	    private final int carrierDispatchExtraDays;
    23	
    24	    Region(String insuranceRate, String insuranceCap, int carrierDispatchExtraDays) {
    25	        this.insuranceRate = new BigDecimal(insuranceRate);
    26	        this.insuranceCap = insuranceCap == null ? null : Money.of(insuranceCap);
    27	        this.carrierDispatchExtraDays = carrierDispatchExtraDays;
    28	    }
    29	
    30	    public static Optional<Region> fromCode(String code) {
    31	        return Arrays.stream(values()).filter(r -> r.name().equals(code)).findFirst();
    32	    }
    33	
    34	    /** Seguro contra extravio e roubo, sobre o valor dos produtos. */
    35	    public BigDecimal insurance(BigDecimal productsSubtotal) {
    36	        BigDecimal insurance = Money.percentOf(productsSubtotal, insuranceRate);
    37	        return insuranceCap == null ? insurance : Money.min(insurance, insuranceCap);
    38	    }
    39	
    40	    public int carrierDispatchExtraDays() {
    41	        return carrierDispatchExtraDays;
    42	    }
    43	}
