     1	package com.loja.orders.payment;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     5	
     6	import org.springframework.stereotype.Component;
     7	
     8	import com.loja.orders.common.Money;
     9	
    10	/** Cartão de crédito: até 3x sem juros; de 4x a 12x com juros mensais pela tabela Price. */
    11	@Component
    12	public class CreditCardPayment implements PaymentMethod {
    13	
    14	    private static final int MAX_INSTALLMENTS = 12;
    15	    private static final int MAX_INTEREST_FREE = 3;
    16	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    17	
    18	    @Override
    19	    public String code() {
    20	        return "CREDIT_CARD";
    21	    }
    22	
    23	    @Override
    24	    public boolean acceptsInstallments(int installments) {
    25	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
    26	    }
    27	
    28	    @Override
    29	    public PaymentTerms terms(PaymentContext context) {
    30	        BigDecimal total = context.orderTotal();
    31	        int n = context.installments();
    32	        if (n <= MAX_INTEREST_FREE) {
    33	            return new PaymentTerms(total, total.divide(BigDecimal.valueOf(n), 2, Money.ROUNDING));
    34	        }
